#!/bin/bash
# Rebuilds transactions.html from the generated partials.
#
# The body is generated by _gen_transactions.py from the twenty-section
# specification, so every numbered sub-item (1.1 … 20.9) is present by
# construction and the figures stay consistent across sections.
set -e
cd "$(dirname "$0")"

python3 _gen_transactions.py
cat _transactions.css _transactions2.css > _transactions-build.css
python3 _compose.py _txhead.html transactions _transactions-build.css

{
  cat _txhead.html
  cat _tx2body.html
  cat _tx2js.js
  printf '</body>\n</html>\n'
} > transactions.html

python3 - <<'PY'
import pathlib
p = pathlib.Path('transactions.html')
s = p.read_text()
s = s.replace('<title>Module — GOLDEN FINANCIAL SERVICES</title>',
              '<title>Transactions — GOLDEN FINANCIAL SERVICES</title>')
p.write_text(s)
print('built transactions.html', len(s), 'bytes')
PY

python3 inject_backnav.py transactions.html
